from collections import Counter,deque
print('input shape rows',len(demo),'widths',set(map(len,demo)))
# list candidate perimeter boxes found from components
bg=Counter(x for row in demo for x in row).most_common(1)[0][0]
seen=set(); frames=[]
for r in range(len(demo)):
 for c in range(len(demo[0])):
  if demo[r][c]==bg or (r,c) in seen: continue
  q=deque([(r,c)]);seen.add((r,c)); cells=[]
  while q:
   x,y=q.popleft();cells.append((x,y))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<len(demo) and 0<=b<len(demo[0]) and (a,b) not in seen and demo[a][b]!=bg:seen.add((a,b));q.append((a,b))
  r0=min(x for x,y in cells);r1=max(x for x,y in cells);c0=min(y for x,y in cells);c1=max(y for x,y in cells)
  peri={(x,y) for x in range(r0,r1+1) for y in range(c0,c1+1) if x in (r0,r1) or y in (c0,c1)}
  if r1-r0>=2 and c1-c0>=2 and len(set(cells))==len(peri) and all(demo[x][y]==demo[r0][c0] for x,y in peri): frames.append((r0,c0,r1,c1,demo[r0][c0]))
print('frames',frames)
